package agentproto

import (
	"errors"
	"regexp"
)

// P-mail operation kinds (MH-577 I1/I2/I3): a Stalwart Mail Server run by the agent as a Docker
// container, with its HTTP management API bound to 127.0.0.1 only (never published). Like every
// other operation kind, nothing in the params reaches a shell verbatim: mail.install turns into a
// fixed `docker run` argv, and mail.domain/mail.mailbox/mail.alias turn into typed HTTP calls the
// agent itself makes to that loopback-only API. The admin secret is generated by the agent and
// reported back sealed to the team; it is never chosen by, or shown in plaintext to, a person.
const (
	KindMailInstall = "mail.install" // run stalwartlabs/stalwart, admin API on 127.0.0.1 only
	KindMailDomain  = "mail.domain"  // add/remove a domain on the mail server; on add, fetch/generate its DKIM key
	KindMailbox     = "mail.mailbox" // create/update/delete a mailbox (Stalwart "individual" principal)
	KindMailAlias   = "mail.alias"   // create/delete an alias or external forward
)

// Mail secrets are sealed the same way every other agent-op secret is (DBSecretContext(id, purpose)
// — see internal/agent/databases.go's openSecret, reused unchanged by mail.install/domain/mailbox):
// "admin" for the management API secret, "mailbox:<email>" for a mailbox's login password.

// MailImage pins the Stalwart image tag the agent runs. Kept in one place so every install (and
// every test) agrees on the exact, checked-in version.
const MailImage = "stalwartlabs/stalwart:v0.13.4"

// MailContainerName / MailVolumeName: the fixed docker names for one team's mail server.
func MailContainerName(id string) string { return NamePrefix + "mail-" + id }
func MailVolumeName(id string) string    { return NamePrefix + "maildata-" + id }

var (
	mailHostnameRE  = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$`)
	mailLocalPartRE = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]{0,62}$`)
)

// ValidMailHostname / ValidMailDomain: a DNS name, same shape for a server's own hostname and a
// hosted domain (both are checked by the schema's CHECK constraints too; this is the agent/service
// side check before either is used in an HTTP call or an argv).
func ValidMailHostname(s string) bool { return len(s) <= 253 && mailHostnameRE.MatchString(s) }
func ValidMailDomain(s string) bool   { return ValidMailHostname(s) }

// ValidMailLocalPart: the left-hand side of a mailbox or alias address.
func ValidMailLocalPart(s string) bool { return mailLocalPartRE.MatchString(s) }

// ---- mail.install ---------------------------------------------------------------------------------

// MailInstallParams / MailInstallResult: mail.install.
type MailInstallParams struct {
	MailServerID string `json:"mail_server_id"`
	Hostname     string `json:"hostname"`
	Container    string `json:"container"`
	Volume       string `json:"volume"`
	Image        string `json:"image"`
	AdminPort    int    `json:"admin_port"` // published on 127.0.0.1 only
	// AdminSecret is the management API admin password, generated by the control plane (never by
	// the agent, never typed by a person) and sealed to this agent's own key with
	// DBSecretContext(mail_server_id, "admin"). Re-running install (resume) sends the same
	// already-generated secret back, so the container's credential never silently changes under it.
	AdminSecret string `json:"admin_secret"`
}

func (p MailInstallParams) Validate() error {
	if p.MailServerID == "" || p.Container == "" || p.Volume == "" || p.Image == "" || p.AdminSecret == "" {
		return errRequired("mail.install: mail_server_id, container, volume, image and admin_secret are required")
	}
	if !ValidMailHostname(p.Hostname) {
		return errRequired("mail.install: hostname is not a valid DNS name")
	}
	if p.AdminPort < 1 || p.AdminPort > 65535 {
		return errRequired("mail.install: admin_port must be a valid port")
	}
	return nil
}

// MailInstallResult reports the running container.
type MailInstallResult struct {
	Container string `json:"container"`
	Volume    string `json:"volume"`
}

// ---- mail.domain ----------------------------------------------------------------------------------

// MailDomainParams / MailDomainResult: mail.domain.
type MailDomainParams struct {
	MailServerID string `json:"mail_server_id"`
	AdminPort    int    `json:"admin_port"`
	AdminSecret  string `json:"admin_secret"` // sealed box, DBSecretContext(mail_server_id, "admin")
	Domain       string `json:"domain"`
	Action       string `json:"action" enum:"create,delete"`
}

func (p MailDomainParams) Validate() error {
	if p.MailServerID == "" || p.AdminSecret == "" {
		return errRequired("mail.domain: mail_server_id and admin_secret are required")
	}
	if !ValidMailDomain(p.Domain) {
		return errRequired("mail.domain: domain is not a valid DNS name")
	}
	if p.Action != "create" && p.Action != "delete" {
		return errRequired("mail.domain: action must be create or delete")
	}
	return nil
}

// MailDomainResult carries the DKIM key Stalwart generated for a created domain (delete: empty).
type MailDomainResult struct {
	DKIMSelector  string `json:"dkim_selector,omitempty"`
	DKIMPublicKey string `json:"dkim_public_key,omitempty" doc:"Base64 public key, as it belongs in the domain's DKIM TXT record."`
}

// ---- mail.mailbox ---------------------------------------------------------------------------------

// MailboxParams / MailboxResult: mail.mailbox.
type MailboxParams struct {
	MailServerID string `json:"mail_server_id"`
	AdminPort    int    `json:"admin_port"`
	AdminSecret  string `json:"admin_secret"` // sealed box, DBSecretContext(mail_server_id, "admin")
	Email        string `json:"email"`        // local@domain
	QuotaMB      int    `json:"quota_mb,omitempty"`
	// PasswordSecret carries the mailbox password on create/update only, sealed to this agent's own
	// key with DBSecretContext(mailbox_id, "mailbox:<email>"). Never present on delete.
	PasswordSecret string `json:"password_secret,omitempty"`
	Action         string `json:"action" enum:"create,update,delete"`
}

func (p MailboxParams) Validate() error {
	if p.MailServerID == "" || p.AdminSecret == "" || p.Email == "" {
		return errRequired("mail.mailbox: mail_server_id, admin_secret and email are required")
	}
	if p.Action != "create" && p.Action != "update" && p.Action != "delete" {
		return errRequired("mail.mailbox: action must be create, update or delete")
	}
	if p.Action != "delete" && p.QuotaMB <= 0 {
		return errRequired("mail.mailbox: quota_mb is required")
	}
	if p.Action == "create" && p.PasswordSecret == "" {
		return errRequired("mail.mailbox: password_secret is required to create a mailbox")
	}
	return nil
}

type MailboxResult struct {
	Email string `json:"email"`
}

// ---- mail.alias -----------------------------------------------------------------------------------

// MailAliasParams / MailAliasResult: mail.alias.
type MailAliasParams struct {
	MailServerID string   `json:"mail_server_id"`
	AdminPort    int      `json:"admin_port"`
	AdminSecret  string   `json:"admin_secret"` // sealed box, DBSecretContext(mail_server_id, "admin")
	Email        string   `json:"email"`        // local@domain
	Destinations []string `json:"destinations,omitempty"`
	Action       string   `json:"action" enum:"create,delete"`
}

func (p MailAliasParams) Validate() error {
	if p.MailServerID == "" || p.AdminSecret == "" || p.Email == "" {
		return errRequired("mail.alias: mail_server_id, admin_secret and email are required")
	}
	if p.Action != "create" && p.Action != "delete" {
		return errRequired("mail.alias: action must be create or delete")
	}
	if p.Action == "create" && len(p.Destinations) == 0 {
		return errRequired("mail.alias: at least one destination is required")
	}
	return nil
}

type MailAliasResult struct {
	Email string `json:"email"`
}

// errRequired is a small helper so every Validate above reads the same as the rest of agentproto's
// (errors.New-based) validation, without repeating the import at each call site.
func errRequired(msg string) error { return errors.New(msg) }
